const crypto = require('crypto');
const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : input;
const requestId = String(body.request_id || body.requestId || crypto.randomUUID());
const idempotencyKey = String(body.idempotency_key || body.idempotencyKey || body.external_message_id || body.message_id || '');
const tenantId = String(body.tenant_id || body.tenantId || '');
const channelConnectionId = String(body.channel_connection_id || body.channelConnectionId || '');
const externalCustomerId = String(body.external_customer_id || body.customer_id || body.customerId || '');
const content = String(body.content || body.message_text || body.message || '').trim();
const externalThreadId = String(body.external_thread_id || body.conversation_id || body.externalThreadId || externalCustomerId);
const externalMessageId = String(body.external_message_id || body.message_id || idempotencyKey);
const missing = [];
for (const [key, value] of Object.entries({ tenant_id: tenantId, channel_connection_id: channelConnectionId, external_customer_id: externalCustomerId, external_thread_id: externalThreadId, external_message_id: externalMessageId, content, request_id: requestId, idempotency_key: idempotencyKey })) {
  if (!value) missing.push(key);
}
if (missing.length) {
  return [{ json: { valid: false, request_id: requestId, error: 'invalid_payload', missing } }];
}
return [{ json: {
  valid: true,
  request_id: requestId,
  idempotency_key: idempotencyKey,
  tenant_id: tenantId,
  channel_connection_id: channelConnectionId,
  external_customer_id: externalCustomerId,
  external_thread_id: externalThreadId,
  external_message_id: externalMessageId,
  content,
  customer_name: String(body.customer_name || body.customer?.name || ''),
  provider_payload: body.provider_payload || body.metadata || {},
  orchestration_trace: [
    'receive_envelope',
    'validate_schema',
    'validate_required_ids',
    'validate_request_id',
    'validate_idempotency_key',
    'resolve_runtime_config',
    'resolve_assistant_config',
    'resolve_channel_config',
    'load_recent_memory',
    'normalize_customer_message',
    'detect_language',
    'detect_prompt_injection',
    'classify_intent',
    'detect_sentiment_urgency',
    'retrieve_tenant_knowledge',
    'evaluate_retrieval_confidence',
    'generate_grounded_answer',
    'independent_grounding_judge',
    'apply_confidence_threshold',
    'apply_knowledge_gap_policy',
    'apply_business_hours_policy',
    'apply_prohibited_topic_policy',
    'determine_handoff',
    'determine_action',
    'determine_approval',
    'schedule_followup_policy',
    'persist_messages_sources_trace_usage_analytics_delivery',
    'classify_provider_and_api_failures',
    'bounded_retry_dead_letter_incident',
    'stable_response_contract'
  ]
} }];

const crypto = require('crypto');
const payload = { ...$json };
delete payload.valid;
const body = JSON.stringify(payload);
const keyId = String($env.REPLYOPS_INTERNAL_KEY_ID || '');
const secret = String($env.REPLYOPS_INTERNAL_KEY_SECRET || '');
const baseUrl = String($env.REPLYOPS_BASE_URL || 'https://replyops.abud.fun').replace(/\/$/, '');
if (!keyId || !secret) throw new Error('replyops_internal_key_missing');
const timestamp = String(Date.now());
const nonce = crypto.randomUUID();
const method = 'POST';
const path = '/api/internal/messages/incoming';
const bodyHash = crypto.createHash('sha256').update(body).digest('hex');
const canonical = [keyId, timestamp, nonce, method, path, bodyHash].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical).digest('hex');
return [{ json: { request_id: payload.request_id, url: `${baseUrl}${path}`, body, headers: { 'content-type': 'application/json', 'x-request-id': payload.request_id, 'x-replyops-key-id': keyId, 'x-replyops-timestamp': timestamp, 'x-replyops-nonce': nonce, 'x-replyops-body-sha256': bodyHash, 'x-replyops-signature': signature } } }];

const input = $input.first().json;
if (input && input.success === true && input.request_id && input.conversation_id) {
  return [{ json: input }];
}
const error = String(input.error || input.message || 'replyops_api_failure');
return [{ json: {
  success: false,
  request_id: String(input.request_id || ''),
  tenant_id: String(input.tenant_id || ''),
  conversation_id: String(input.conversation_id || ''),
  reply: null,
  intent: 'unknown',
  language: 'unknown',
  sentiment: 'neutral',
  confidence: 0,
  knowledge_gap: true,
  grounding_accepted: false,
  handoff_required: true,
  handoff_reason: 'replyops_api_failure',
  action: { type: 'none', status: 'not_required', requires_approval: false, request_id: null },
  followup: { scheduled: false, job_id: null },
  sources: [],
  usage: {},
  timings: {},
  error
} }];
